<script setup>
import { computed, nextTick, ref, watch } from 'vue'
import FigmaPdfVorschau from './FigmaPdfVorschau.vue'
const props = defineProps({ step: { type: Number, default: 1 } })
const heading = ref(null)
const link = step => ({ name: 'medientechnik-figma-tutorial-3', params: { step } })
const steps = [
  { title: 'Vorlage untersuchen', minutes: 10, session: 1, intro: 'Du baust die Smartphone-Startseite in Figma nach.', instructions: ['Öffne die Vorlage „Home.pdf“ über den Link unten und sieh sie von oben bis unten an.', 'Benenne die Bereiche: Statuszeile, Suchfeld, Werbebanner, Kategorien, Produktkarten und untere Navigation (Tab Bar).', 'Beobachte: Die Produktkarten stehen in zwei Spalten; die Seite ist deutlich höher als ein einzelner Bildschirm.', 'Lade „Assets.zip“ über den Download unten herunter und entpacke die Datei. Sie enthält Bilder, Icons und Piktogramme.'], check: 'Du kannst die Hauptbereiche der Vorlage benennen.' },
  { title: 'Frame für die lange Smartphone-Seite', minutes: 15, session: 1, intro: 'Ein Frame begrenzt die Gestaltung. Für diesen Auftrag benötigst du eine hochformatige, lange Smartphone-Seite.', instructions: ['Erstelle eine neue Figma-Designdatei im Bereich „Drafts“ / „Entwürfe“ und benenne sie „Einkaufs-App“. Wähle anschließend das Frame-Werkzeug (F).', 'Ziehe einen neuen Frame auf oder wähle eine Smartphone-Vorlage. Stelle im rechten Eigenschaftenbereich W auf 414 und H auf 1458 ein.', 'Benenne den Frame „Home – Nachbau“.'], check: 'Ein weißer Frame „Home – Nachbau“ mit 414 × 1458 liegt in deiner Datei.' },
  { title: 'Kopfbereich und Suchfeld', minutes: 15, session: 1, intro: 'Beginne mit den großen Formen und Abständen im oberen Bereich.', instructions: ['Untersuche die Vorlage: Oben stehen die Uhrzeit und kleine Statussymbole; darunter liegt ein hellgraues Suchfeld.', 'Ziehe ein Rechteck für das Suchfeld und gib ihm eine hellgraue Füllung sowie leicht gerundete Ecken.', 'Suche im entpackten Ordner „icons“ passende Symbole für Suche und Filter. Ziehe sie in die Figma-Datei und passe ihre Größe an.', 'Setze mit dem Textwerkzeug (T) die Uhrzeit und „Search keywords..“ ein. Vergleiche Größe und Abstand zur Vorlage.'], check: 'Statuszeile und Suchfeld sind angelegt; Symbole sind als Platzhalter erkennbar.' },
  { title: 'Werbebanner gestalten', minutes: 20, session: 1, intro: 'Baue das Werbebanner mit dem bereitgestellten Bild und den darüberliegenden Elementen nach.', instructions: ['Ziehe die Datei „img_01.png“ aus dem entpackten Asset-Ordner in Figma.', 'Ergänze den Text „20% off on your first purchase“ als eigene Textebene und positioniere ihn im unteren Bereich des Banners.', 'Erstelle die kleine grüne Markierung und die hellen Punkte unten links aus einfachen Formen.'], check: 'Das Banner nimmt den passenden Raum ein; Text und Punktmarkierung liegen als eigene Elemente darauf.' },
  { title: 'Kategorien anlegen', minutes: 20, session: 1, intro: 'Die Kategorien bilden eine waagerechte Reihe aus farbigen Kreisen mit Beschriftung.', instructions: ['Setze die Überschrift „Categories“ unter das Banner. Suche den passenden Pfeil im Ordner „icons“ und füge ihn rechts neben der Überschrift ein.', 'Zeichne einen Kreis für die erste Kategorie. Halte beim Aufziehen die Umschalttaste gedrückt, um einen Kreis zu erhalten.', 'Dupliziere den Kreis mehrfach und ordne die Kreise nebeneinander an. Gib ihnen unterschiedliche helle Füllfarben.', 'Ergänze unter den ersten fünf Kreisen „Vegetables“, „Fruits“, „Beverages“, „Grocery“ und „Edible oil“. Suche passende SVG-Dateien im Ordner „pictograms“ und platziere sie auf den Kreisen.', 'Vergleiche die Reihe mit der Vorlage: Am rechten Rand ist eine weitere Kategorie angeschnitten. Nutze den sichtbaren Bereich des Frames als Orientierung.'], check: 'Überschrift, Kategorienreihe und Beschriftungen entsprechen dem Aufbau der Vorlage.' },
  { title: 'Produktbereich vorbereiten', minutes: 15, session: 2, intro: 'Im unteren Hauptbereich stehen Produktkarten in einem zweispaltigen Raster.', instructions: ['Setze unter die Kategorien die Überschrift „Featured products“ mit dem jeweiligen Icon.', 'Lege nun einen Verlauf nach Hellgrau über die gesamte Seite an.', 'Zeichne darauf eine weiße Produktkarte. Sie soll ungefähr die halbe verfügbare Breite einnehmen; lasse Platz für einen Zwischenraum und die zweite Karte.', 'Achte in der Ebenenliste darauf, dass der Hintergrund hinter der Produktkarte liegt.'], check: 'Produktbereich und erste weiße Karte liegen unterhalb der Kategorien.' },
  { title: 'Erste Produktkarte aufbauen', minutes: 20, session: 2, intro: 'Die erste Karte dient als Grundlage für weitere Karten. Verwende die bereitgestellten Produktbilder und Icons.', instructions: ['Erstelle im oberen Teil der Karte einen pastellfarbenen Kreis. Ziehe „peach-24 1.png“ aus dem Ordner „fruit pics“ darüber und passe die Größe an.', 'Ergänze oben rechts das passende Herz-Icon aus dem Ordner „icons“.', 'Füge mit dem Textwerkzeug Preis „$8.00“, Produktname „Fresh Peach“ und Mengenangabe „dozen“ als getrennte Textebenen hinzu.', 'Zeichne eine feine horizontale Trennlinie und ergänze darunter „Add to cart“ sowie ein passendes Icon aus dem Asset-Ordner.', 'Vergleiche die Abstände und Textgrößen mit der Vorlage.'], check: 'Die erste Karte enthält Produktbild, Herz, Preis, Produktname, Menge und Aktionsbereich.' },
  { title: 'Inhalte und Varianten ergänzen', minutes: 20, session: 2, intro: 'Passe die Kopien an die unterschiedlichen Produkte und Zustände der Vorlage an.', instructions: ['Übertrage die Produktnamen, Preise und Mengen aus der PDF in andere Karten. Orientiere dich am sichtbaren Originaltext.', 'Gib den Kreisen unterschiedliche Pastelltöne und ersetze die kopierten Produktbilder durch die passenden PNG-Dateien aus „fruit pics“.', 'Ergänze die sichtbaren „NEW“- und „-16%“-Markierungen sowie ausgefüllte und nicht ausgefüllte Herz-Icons.', 'Ersetze bei zwei Karten den „Add to cart“-Bereich durch eine einfache Mengenanzeige mit Minus, Zahl und Plus.'], check: 'Die sechs Karten zeigen die wichtigsten Unterschiede der Vorlage.' },
  { title: 'Tab Bar aufbauen', minutes: 15, session: 2, intro: 'Baue die untere Navigationsleiste der Einkaufs-App nach.', instructions: ['Zeichne am unteren Rand des Frames eine weiße Fläche für die Tab Bar.', 'Suche im Ordner „icons“ die passenden Symbole für Startseite, Konto, Favoriten und Einkaufswagen. Füge sie in die Figma-Datei ein.', 'Ordne die vier Icons in der Leiste an und orientiere dich dabei an den Abständen in der Vorlage.', 'Zeichne hinter dem Einkaufswagen einen grünen Kreis und platziere das Einkaufswagen-Icon darüber.', 'Prüfe, ob alle Elemente innerhalb des Frames liegen und die Icons gut erkennbar sind.'], check: 'Die Tab Bar enthält vier Icons; der Einkaufswagen ist mit einem grünen Kreis hervorgehoben.' }
]
const current = computed(() => steps[props.step - 1])
watch(() => props.step, async () => { await nextTick(); heading.value?.focus() })
</script>

