    <nav class="step-links" aria-label="Schritte dieses Tutorials"><RouterLink v-for="(item, index) in steps" :key="item.title" :to="link(index + 1)" :aria-current="step === index + 1 ? 'step' : undefined" :aria-label="`Schritt ${index + 1}: ${item.title}`">{{ index + 1 }}</RouterLink></nav>
    <figure v-if="step === 1" class="reference-image"><div class="pdf-reference"><FigmaPdfVorschau src="/medientechnik/figma/uebung-home/Home.pdf" /></div><figcaption>Vorlage: Startseite der Einkaufs-App · <a href="/medientechnik/figma/uebung-home/Home.pdf" target="_blank" rel="noopener noreferrer">PDF in neuem Tab öffnen ↗</a></figcaption></figure>
    <figure v-if="step === 2" class="reference-image frame-image"><a href="/medientechnik/figma/uebung-home/home-frame.png" target="_blank" rel="noopener noreferrer"><img src="/medientechnik/figma/uebung-home/home-frame.png" alt="Figma-Designdatei Einkaufs-App mit ausgewähltem Frame Home – Nachbau und den Maßen 414 × 1458" /></a><figcaption>Der Frame „Home – Nachbau“ mit Breite 414 und Höhe 1458 · Anklicken zum Vergrößern</figcaption></figure>
    <figure v-if="step === 3" class="reference-image frame-image"><a href="/medientechnik/figma/uebung-home/home-suchfeld.png" target="_blank" rel="noopener noreferrer"><img src="/medientechnik/figma/uebung-home/home-suchfeld.png" alt="Figma-Frame der Einkaufs-App mit Statuszeile und Suchfeld" /></a><figcaption>Statuszeile und Suchfeld in der Figma-Datei · Anklicken zum Vergrößern</figcaption></figure>
    <figure v-if="step === 4" class="reference-image frame-image"><a href="/medientechnik/figma/uebung-home/home-banner.png" target="_blank" rel="noopener noreferrer"><img src="/medientechnik/figma/uebung-home/home-banner.png" alt="Figma-Frame der Einkaufs-App mit Suchfeld und eingefügtem Werbebanner" /></a><figcaption>Das Werbebanner in der Figma-Datei · Anklicken zum Vergrößern</figcaption></figure>
    <figure v-if="step === 5" class="reference-image frame-image"><a href="/medientechnik/figma/uebung-home/home-kategorien.png" target="_blank" rel="noopener noreferrer"><img src="/medientechnik/figma/uebung-home/home-kategorien.png" alt="Figma-Frame der Einkaufs-App mit Werbebanner und Kategorienreihe" /></a><figcaption>Die Kategorien in der Figma-Datei · Anklicken zum Vergrößern</figcaption></figure>
    <figure v-if="step === 6" class="reference-image frame-image"><a href="/medientechnik/figma/uebung-home/home-produktbereich.png" target="_blank" rel="noopener noreferrer"><img src="/medientechnik/figma/uebung-home/home-produktbereich.png" alt="Figma-Entwurf mit Kategorien, Überschrift Featured products und erster Produktkartenfläche" /></a><figcaption>Der vorbereitete Produktbereich · Anklicken zum Vergrößern</figcaption></figure>
    <figure v-if="step === 7" class="reference-image frame-image"><a href="/medientechnik/figma/uebung-home/home-produktkarte.png" target="_blank" rel="noopener noreferrer"><img src="/medientechnik/figma/uebung-home/home-produktkarte.png" alt="Figma-Entwurf mit der ersten Produktkarte für Fresh Peach" /></a><figcaption>Die erste Produktkarte · Anklicken zum Vergrößern</figcaption></figure>
    <figure v-if="step === 8" class="reference-image frame-image"><a href="/medientechnik/figma/uebung-home/home-produktkarten.png" target="_blank" rel="noopener noreferrer"><img src="/medientechnik/figma/uebung-home/home-produktkarten.png" alt="Figma-Entwurf der Einkaufs-App mit sechs ausgearbeiteten Produktkarten" /></a><figcaption>Die ausgearbeiteten Produktkarten · Anklicken zum Vergrößern</figcaption></figure>
    <figure v-if="step === 9" class="reference-image frame-image"><a href="/medientechnik/figma/uebung-home/home-tab-bar.png" target="_blank" rel="noopener noreferrer"><img src="/medientechnik/figma/uebung-home/home-tab-bar.png" alt="Figma-Entwurf der Einkaufs-App mit Tab Bar und hervorgehobenem Einkaufswagen" /></a><figcaption>Die Tab Bar der Einkaufs-App · Anklicken zum Vergrößern</figcaption></figure>
    <section class="practice"><h2>{{ step }}. {{ current.title }}</h2><p>{{ current.intro }}</p><ol><li v-for="instruction in current.instructions" :key="instruction">{{ instruction }}</li></ol></section>
